  ('technology.s03_eyebrow', 'Advanced Visual Field Testing'),
  ('technology.s03_heading', 'See More.' || char(10) || 'Know More.'),
  ('technology.s03_text', 'Using cutting-edge virtual reality and AI-powered technology, RetinaLogik visual field testing provides a fast, accurate and comfortable way to assess your peripheral vision.'),
  ('technology.s04_title', 'Inside Our Optometry Clinic'),
  ('technology.s04_title2', 'In-House Edging Lab'),
  ('technology.s04_text', 'Our computerized, automated edging system and in-house optical lab let us cut and fit lenses efficiently, decreasing turnaround so you get your eyewear sooner.'),
  ('technology.s04_title3', 'Optical Coherence Tomography (OCT)'),
  ('technology.s04_text2', 'Our Topcon Maestro 2 OCT captures high-resolution, cross-sectional images of the retina, non-invasively, to detect and monitor retinal disease within minutes.'),
  ('technology.s04_title4', 'RetinaLogik Visual Field Testing'),
  ('technology.s04_text3', 'Our RetinaLogik perimeter uses virtual reality and AI to map your full scope of vision and help detect glaucoma and other conditions, quickly and comfortably.'),
  ('technology.s04_title5', 'Digital Retinal Imaging'),
  ('technology.s04_text4', 'A digital photo of the back of your eye, showing the retina, optic disc and blood vessels, helps us pinpoint early signs of disease.'),
